-- Kestrel Health Network SQL lab seed (SQLite). All data is synthetic; patients are never named.
-- Generated by generate.py (seed 20261001). Load with:  sqlite3 kestrel_lab.db < khn_lab.sql
-- Logical foreign keys (deliberately NOT enforced, so you can find the orphans):
--   staff.manager_id -> staff.employee_id
--   staff.site_code -> sites.site_code
--   security_events.asset_id -> assets.asset_id
--   service_tickets.site_code -> sites.site_code
-- staff holds the latest assignment row per employee from khn_identity.csv.
-- service_tickets holds the first 30 unique tickets opened from 2026-09-01. In this lab copy, SD-10113 was keyed with site_code 'PGC' (a typing error for PGH) so the table has an orphan site.

DROP TABLE IF EXISTS service_tickets;
DROP TABLE IF EXISTS security_events;
DROP TABLE IF EXISTS assets;
DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS sites;

CREATE TABLE sites (
  site_code TEXT PRIMARY KEY,
  site_name TEXT NOT NULL,
  zone TEXT NOT NULL,
  site_type TEXT NOT NULL
);
CREATE TABLE staff (
  employee_id TEXT PRIMARY KEY,
  full_name TEXT NOT NULL,
  job_role TEXT,
  department TEXT,
  site_code TEXT,
  manager_id TEXT,
  worker_type TEXT,
  hr_status TEXT,
  account_status TEXT,
  privileged TEXT,
  mfa_enrolled TEXT,
  effective_from TEXT,
  effective_to TEXT
);
CREATE TABLE assets (
  asset_id TEXT PRIMARY KEY,
  system_name TEXT NOT NULL,
  tier INTEGER,
  business_owner_id TEXT,
  custodian_id TEXT,
  classification TEXT,
  hosting TEXT,
  vendor_id TEXT,
  rto_target_hours REAL,
  rpo_target_hours REAL,
  end_of_support_date TEXT
);
CREATE TABLE security_events (
  record_id TEXT PRIMARY KEY,
  record_type TEXT NOT NULL,
  occurred_at TEXT,
  opened_at TEXT,
  detected_at TEXT,
  contained_at TEXT,
  recovered_at TEXT,
  severity TEXT,
  category TEXT,
  asset_id TEXT,
  status TEXT,
  remediation_due TEXT,
  cvss_score REAL
);
CREATE TABLE service_tickets (
  ticket_id TEXT PRIMARY KEY,
  ticket_type TEXT NOT NULL,
  opened_at TEXT NOT NULL,
  resolved_at TEXT,
  priority TEXT,
  category TEXT,
  site_code TEXT,
  assignment_group TEXT,
  sla_target_hours REAL,
  sla_met TEXT
);

