-- Reconciliation queries and their exact expected results.
-- Computed by generate.py by running this file with Python sqlite3.
-- Row counts: sites 4, staff 42, assets 15, security_events 20, service_tickets 30.
--
-- Q1. Staff whose manager_id has no matching staff row (orphan manager)
--   SELECT s.employee_id, s.manager_id
--   FROM staff AS s
--   LEFT JOIN staff AS m ON m.employee_id = s.manager_id
--   WHERE s.manager_id IS NOT NULL AND m.employee_id IS NULL
--   ORDER BY s.employee_id;
-- Expected result:
--   employee_id | manager_id
--   E-037 | E-099
--   (1 row)
--
-- Q2. Security events whose asset_id has no matching asset (orphan asset)
--   SELECT e.record_id, e.asset_id
--   FROM security_events AS e
--   LEFT JOIN assets AS a ON a.asset_id = e.asset_id
--   WHERE a.asset_id IS NULL
--   ORDER BY e.record_id;
-- Expected result:
--   record_id | asset_id
--   SEC-016 | A-021
--   (1 row)
--
-- Q3. Service tickets whose site_code has no matching site (orphan site)
--   SELECT t.ticket_id, t.site_code
--   FROM service_tickets AS t
--   LEFT JOIN sites AS s ON s.site_code = t.site_code
--   WHERE s.site_code IS NULL
--   ORDER BY t.ticket_id;
-- Expected result:
--   ticket_id | site_code
--   SD-10113 | PGC
--   (1 row)
--
-- Q4. Tickets per site with an Unknown member, so the rows add back to the table total
--   SELECT COALESCE(s.site_code, 'Unknown') AS site, COUNT(*) AS tickets
--   FROM service_tickets AS t
--   LEFT JOIN sites AS s ON s.site_code = t.site_code
--   GROUP BY COALESCE(s.site_code, 'Unknown')
--   ORDER BY site;
-- Expected result:
--   site | tickets
--   ARH | 6
--   CVH | 8
--   KGH | 13
--   PGH | 2
--   Unknown | 1
--   (5 rows)
--
